// ============================================================
// Merge: WoodstockState
// ============================================================
// MergeWoodstockState fills zero-valued fields in dst from src.
func MergeWoodstockState(dst, src *WoodstockState) {
	if dst.TaskQueue == nil {
		dst.TaskQueue = src.TaskQueue
	} else if src.TaskQueue != nil {
		MergeTaskItem(dst.TaskQueue, src.TaskQueue)
	}
	if dst.EventStream == nil {
		dst.EventStream = src.EventStream
	} else if src.EventStream != nil {
		MergeEventData(dst.EventStream, src.EventStream)
	}
	if dst.Status == nil {
		dst.Status = src.Status
	} else if src.Status != nil {
		MergeServiceStatus(dst.Status, src.Status)
	}
}

